// Called only by authenticated Node dispatch once consent + OTP are persisted.
// The flags are informational defense-in-depth; the future Node authorization
// handler must validate them against durable quote/OTP state before dispatch.
const b = $input.first().json.body ?? {};
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(b.agentKey!=='ancfz'||b.otpVerified!==true||b.customerConsent!==true) throw new Error('ANCFZ approval missing');
if(typeof b.ticketId!=='string'||!uuid.test(b.ticketId)) throw new Error('Invalid ticket ID');
if(typeof b.quotationId!=='string'||!uuid.test(b.quotationId)) throw new Error('Invalid quotation ID');
if(typeof b.externalReference!=='string'||!/^ANCFZ-[A-Za-z0-9_-]{8,160}$/.test(b.externalReference)) throw new Error('Invalid stable external reference');
if(b.currency!=='AED') throw new Error('ANCFZ demo accepts AED quote only');
if(typeof b.amount!=='string'||! /^(?:0|[1-9]\d{0,7})\.\d{2}$/.test(b.amount)|| Number(b.amount)<=0) throw new Error('Expected approved decimal amount, e.g. 10.00');
if(typeof b.firstName!=='string'||!b.firstName.trim()||b.firstName.length>100) throw new Error('Invalid billing first name');
if(typeof b.email!=='string'||b.email.length>254||!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(b.email)) throw new Error('Invalid billing email');
if(typeof b.countryCode!=='string'||!/^[A-Z]{2}$/.test(b.countryCode)) throw new Error('Invalid country code');
return [{json:{agentKey:'ancfz',ticketId:b.ticketId,quotationId:b.quotationId,externalReference:b.externalReference,currency:'AED',amount:b.amount,firstName:b.firstName.trim(),email:b.email.trim(),countryCode:b.countryCode}}];

// The supplied demo Orders endpoint is not the /api/pg/{slug}/init API.
// Do not invent a checkout URL or report an order as paid.
const raw=$input.first().json;
const r=(raw && typeof raw==='object' && !Array.isArray(raw))?raw:{};
const expected=$('Validate Authorized Payment').first().json;
const ref=r.order_number ?? r.OrderNumber ?? r.OrderReference ?? r.order_id ?? r.id;
if((typeof ref!=='string'&&typeof ref!=='number')||!String(ref).trim()||String(ref).length>200) throw new Error('MockGateway Orders response has no verifiable order reference');
const maybeUrl=r.payment_url ?? r.paymentUrl ?? r.checkout_url ?? r.PaymentURL ?? r.PaymentUrl;
let paymentUrl=null;
if(typeof maybeUrl==='string'&&maybeUrl.length<2048){
  let u;
  try { u=new URL(maybeUrl); } catch { throw new Error('Invalid gateway checkout URL'); }
  if(u.protocol!=='https:'||!(u.hostname==='mockgateway.com'||u.hostname.endsWith('.mockgateway.com'))) throw new Error('Untrusted checkout URL');
  paymentUrl=maybeUrl;
}
return [{json:{status:paymentUrl?'checkout_available':'order_created_checkout_unavailable',verified:false,provider:'mockgateway_demo_orders',orderReference:String(ref),paymentUrl,ticketId:expected.ticketId,quotationId:expected.quotationId,externalReference:expected.externalReference,amount:expected.amount,currency:expected.currency}}];
